import 'package:gp/screens/login_page.dart';
import 'package:gp/screens/signup_page.dart';
import 'package:gp/screens/otp_page.dart';
import 'package:gp/screens/edit_profile_page.dart';
import 'package:gp/screens/change_password_page.dart';
import 'package:gp/screens/forgot_password_page.dart';
import 'package:gp/providers/settings_provider.dart';
import 'package:gp/providers/booking_provider.dart';
import 'package:gp/providers/destination_provider.dart';
import 'package:gp/providers/profile_provider.dart';
import 'package:gp/providers/auth_provider.dart';
import 'package:gp/providers/package_provider.dart';
import 'package:gp/providers/review_provider.dart';
import 'package:gp/providers/complaint_provider.dart';
import 'package:gp/providers/notification_provider.dart';
import 'package:gp/providers/payment_provider.dart';
import 'package:gp/providers/ai_advisor_provider.dart';

import 'package:gp/screens/splash_page.dart';

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MultiProvider(
      providers: [
        ChangeNotifierProvider(create: (_) => SettingsProvider()),
        ChangeNotifierProvider(create: (_) => BookingProvider()),
        ChangeNotifierProvider(create: (_) => DestinationProvider()),
        ChangeNotifierProvider(create: (_) => ProfileProvider()),
        ChangeNotifierProvider(create: (_) => AuthProvider()),
        ChangeNotifierProvider(create: (_) => PackageProvider()),
        ChangeNotifierProvider(create: (_) => ReviewProvider()),
        ChangeNotifierProvider(create: (_) => ComplaintProvider()),
        ChangeNotifierProvider(create: (_) => NotificationProvider()),
        ChangeNotifierProvider(create: (_) => PaymentProvider()),
        // Held above the navigation tree so the travel assistant conversation survives tab changes.
        ChangeNotifierProvider(create: (_) => AiAdvisorProvider()),
      ],
      child: Consumer<SettingsProvider>(
        builder: (context, settings, child) {
          return MaterialApp(
            title: 'Xenon',
            debugShowCheckedModeBanner: false,
            theme: AppTheme.lightTheme,
            darkTheme: AppTheme.darkTheme,
            themeMode: settings.themeMode,
            locale: settings.locale,
            localizationsDelegates: const [
              GlobalMaterialLocalizations.delegate,
              GlobalWidgetsLocalizations.delegate,
              GlobalCupertinoLocalizations.delegate,
            ],
            supportedLocales: const [Locale('en'), Locale('ar')],
            initialRoute: '/',
            routes: {
              '/': (context) => const SplashPage(),
              '/login': (context) => const LoginPage(),
              '/signup': (context) => const SignUpPage(),
              '/main': (context) => const MainLayout(),
              '/otp': (context) => const OtpPage(),
              '/edit-profile': (context) => const EditProfilePage(),
              '/change-password': (context) => const ChangePasswordPage(),
              '/forgot-password': (context) => const ForgotPasswordPage(),
            },
          );
        },
      ),
    );
  }
}

