import 'package:flutter/material.dart';
import 'package:gp/models/auth_model.dart';
import 'package:gp/models/api_client.dart';
import 'package:gp/utils/toast_utils.dart';
import 'package:intl/intl.dart';

class SignupProvider extends ChangeNotifier {
  final TextEditingController fullNameController = TextEditingController();
  final TextEditingController emailController = TextEditingController();
  final TextEditingController phoneController = TextEditingController();
  final TextEditingController passwordController = TextEditingController();
  final TextEditingController confirmPasswordController =
      TextEditingController();

  bool _obscurePassword = true;
  bool _obscureConfirmPassword = true;
  bool _isLoading = false;

  bool _hasMinLength = false;
  bool _hasCapital = false;
  bool _hasNumber = false;
  bool _hasSpecial = false;
  bool _passwordsMatch = false;

  String? _gender;
  DateTime? _dateOfBirth;

  SignupProvider() {
    passwordController.addListener(_validatePassword);
    confirmPasswordController.addListener(_validatePassword);
  }

  void _validatePassword() {
    final password = passwordController.text;
    final confirm = confirmPasswordController.text;

    _hasMinLength = password.length >= 8;
    _hasCapital = password.contains(RegExp(r'[A-Z]'));
    _hasNumber = password.contains(RegExp(r'[0-9]'));
    _hasSpecial = password.contains(RegExp(r'[!@#$%^&*(),.?":{}|<>\-\_]'));
    _passwordsMatch = password.isNotEmpty && password == confirm;

    notifyListeners();
  }

  bool get obscurePassword => _obscurePassword;
  bool get obscureConfirmPassword => _obscureConfirmPassword;
  bool get isLoading => _isLoading;

  bool get hasMinLength => _hasMinLength;
  bool get hasCapital => _hasCapital;
  bool get hasNumber => _hasNumber;
  bool get hasSpecial => _hasSpecial;
  bool get passwordsMatch => _passwordsMatch;

  String? get gender => _gender;
  DateTime? get dateOfBirth => _dateOfBirth;

  void setGender(String? value) {
    _gender = value;
    notifyListeners();
  }

  void setDateOfBirth(DateTime? value) {
    _dateOfBirth = value;
    notifyListeners();
  }

  bool get isPasswordValid =>
      _hasMinLength &&
      _hasCapital &&
      _hasNumber &&
      _hasSpecial &&
      _passwordsMatch;
  bool get isFormValid =>
      isPasswordValid &&
      _gender != null &&
      _dateOfBirth != null &&
      fullNameController.text.isNotEmpty &&
      emailController.text.isNotEmpty &&
      phoneController.text.isNotEmpty;

  int get passwordStrengthLevel {
    if (passwordController.text.isEmpty) return 0;
    int metConditions = 0;
    if (_hasMinLength) metConditions++;
    if (_hasCapital) metConditions++;
    if (_hasNumber) metConditions++;
    if (_hasSpecial) metConditions++;

    if (metConditions <= 1) return 1; // Weak
    if (metConditions <= 3) return 2; // Medium
    return 3; // Strong
  }

  void togglePasswordVisibility() {
    _obscurePassword = !_obscurePassword;
    notifyListeners();
  }

  void toggleConfirmPasswordVisibility() {
    _obscureConfirmPassword = !_obscureConfirmPassword;
    notifyListeners();
  }

  Future<void> signup(BuildContext context) async {
    if (!isFormValid) {
      showTopToast(
        context,
        'Please fill in all required fields.',
        isError: true,
      );
      return;
    }

    _isLoading = true;
    notifyListeners();

    final formattedDate = DateFormat('dd/MM/yyyy').format(_dateOfBirth!);

    try {
      await AuthService.sendOtp(emailController.text.trim());
      _isLoading = false;
      notifyListeners();

      if (context.mounted) {
        Navigator.pushReplacementNamed(
          context,
          '/otp',
          arguments: {
            'email': emailController.text.trim(),
            'name': fullNameController.text.trim(),
            'password': passwordController.text,
            'confirmPassword': confirmPasswordController.text,
            'gender': _gender!,
            'mobileNumber': phoneController.text.trim(),
            'dateOfBirth': formattedDate,
            'isRegistration': true,
          },
        );
      }
    } catch (e) {
      _isLoading = false;
      notifyListeners();
      if (context.mounted) {
        String errorMsg = 'Failed to send OTP';
        if (e is ApiException) errorMsg = e.message;
        showTopToast(context, errorMsg, isError: true);
      }
    }
  }

  void continueWithGoogle() {
    // Implement Google login
  }

  void continueWithApple() {
    // Implement Apple login
  }

  @override
  void dispose() {
    fullNameController.dispose();
    emailController.dispose();
    phoneController.dispose();
    passwordController.removeListener(_validatePassword);
    passwordController.dispose();
    confirmPasswordController.removeListener(_validatePassword);
    confirmPasswordController.dispose();
    super.dispose();
  }
}

