                            'Sign up',
                            style: TextStyle(
                              color: AppColors.primaryRust,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 40),
                  ],
                ),
              ).animate().fade(duration: 600.ms).slideY(begin: 0.1, end: 0, curve: Curves.easeOut),
            ],
          ),
        ),
      ),
    );
  }
}

