import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import 'package:gp/theme/colors.dart';
import 'package:gp/providers/profile_provider.dart';
import 'package:gp/providers/settings_provider.dart';
import 'package:gp/widgets/compass_loading_overlay.dart';

class ProfilePage extends StatelessWidget {
  const ProfilePage({super.key});

  @override
  Widget build(BuildContext context) {
    return const _ProfilePageContent();
  }
}

class _ProfilePageContent extends StatelessWidget {
  const _ProfilePageContent();

  @override
  Widget build(BuildContext context) {
    final provider = context.watch<ProfileProvider>();
    final settings = context.watch<SettingsProvider>();
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final isArabic = settings.locale.languageCode == 'ar';

    return Scaffold(
      backgroundColor: isDark
          ? AppColors.backgroundDark
          : AppColors.backgroundLight,
      body: CompassLoadingOverlay(
        isLoading: provider.isLoading,
        child: SafeArea(
          child: SingleChildScrollView(
            padding: const EdgeInsets.symmetric(
              horizontal: 24.0,
              vertical: 16.0,
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                // Header
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      isArabic ? 'أهلاً وسهلاً' : 'Ahlan wa Sahlan',
                      style: TextStyle(
                        color: AppColors.primaryRust,
                        fontSize: 24,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  ],
                ),

                const SizedBox(height: 40),

                // Avatar
                Container(
                  width: 100,
                  height: 100,
                  decoration: BoxDecoration(
                    color: const Color(0xFFE2E8F0), // Light bluish grey
                    shape: BoxShape.circle,
                  ),
                  child: Center(
                    child: Icon(
                      Icons.person_outline,
                      size: 40,
                      color: AppColors.primaryRust,
                    ),
                  ),
                ),

                const SizedBox(height: 16),

                // Edit Profile Link
                GestureDetector(
                  onTap: () => provider.navigateToEditProfile(context),
                  child: Text(
                    isArabic ? 'تعديل تفاصيل الحساب' : 'Edit Profile Details',
                    style: TextStyle(
                      color: AppColors.primaryRust,
                      fontSize: 14,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ),

                const SizedBox(height: 24),

                // User Info
                Text(
                  provider.profile?.name ?? 'User Name',
                  style: TextStyle(
                    color: isDark
                        ? AppColors.textPrimaryDark
                        : AppColors.textPrimaryLight,
                    fontSize: 20,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                const SizedBox(height: 4),
                Text(
                  provider.profile?.email ?? 'user@email.com',
                  style: TextStyle(
                    color: isDark
                        ? AppColors.textSecondaryDark
                        : AppColors.textSecondaryLight,
                    fontSize: 16,
                  ),
                ),

                const SizedBox(height: 40),

                // Menu Options
                _buildMenuTile(
                  icon: Icons.account_balance_wallet_outlined,
                  title: isArabic ? 'طريقة الدفع: كليك (CliQ)' : 'Payment Method: CliQ',
                  onTap: () {
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                        content: Text(
                          isArabic ? 'الدفع عبر كليك هو الطريقة الوحيدة المدعومة حالياً' : 'CliQ is currently the only supported payment method',
                        ),
                      ),
                    );
                  },
                  isDark: isDark,
                ),
                _buildMenuTile(
                  icon: Icons.lock_reset_outlined,
                  title: isArabic ? 'إعادة تعيين كلمة المرور' : 'Reset Password',
                  onTap: () => provider.navigateToResetPassword(context),
                  isDark: isDark,
                ),

                const SizedBox(height: 48),

                // Logout Button
                SizedBox(
                  width: double.infinity,
                  child: ElevatedButton.icon(
                    onPressed: () => provider.logout(context),
                    icon: const Icon(Icons.logout, color: Color(0xFFA02B2B)),
                    label: Text(
                      isArabic ? 'تسجيل الخروج' : 'Log Out',
                      style: const TextStyle(
                        color: Color(0xFFA02B2B),
                        fontSize: 16,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: const Color(0xFFFFE5E5),
                      padding: const EdgeInsets.symmetric(vertical: 16),
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(16),
                      ),
                      elevation: 0,
                    ),
                  ),
                ),

                const SizedBox(height: 24),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildMenuTile({
    required IconData icon,
    required String title,
    required VoidCallback onTap,
    required bool isDark,
  }) {
    return Container(
      margin: const EdgeInsets.only(bottom: 16),
      decoration: BoxDecoration(
        color: isDark ? AppColors.surfaceDark : AppColors.surfaceLight,
        borderRadius: BorderRadius.circular(16),
        boxShadow: isDark
            ? []
            : [
                BoxShadow(
                  color: Colors.black.withValues(alpha: 0.02),
                  blurRadius: 10,
                  offset: const Offset(0, 4),
                ),
              ],
      ),
      child: ListTile(
        contentPadding: const EdgeInsets.symmetric(horizontal: 20, vertical: 8),
        leading: Container(
          padding: const EdgeInsets.all(8),
          decoration: BoxDecoration(
            color: isDark ? AppColors.cardBgDark : const Color(0xFFF0EDEB),
            shape: BoxShape.circle,
          ),
          child: Icon(icon, color: AppColors.primaryRust, size: 24),
        ),
        title: Text(
          title,
          style: TextStyle(
            color: isDark
                ? AppColors.textPrimaryDark
                : AppColors.textPrimaryLight,
            fontSize: 16,
            fontWeight: FontWeight.bold,
          ),
        ),
        trailing: Icon(
          Icons.chevron_right,
          color: isDark
              ? AppColors.textSecondaryDark
              : AppColors.textSecondaryLight,
        ),
        onTap: onTap,
      ),
    );
  }
}

