import 'package:flutter/material.dart';
import 'package:gp/theme/colors.dart';

/// Reusable booking card extracted from bookings_page.dart.
class BookingCard extends StatelessWidget {
  final String title;
  final String date;
  final String status;
  final Color statusColor;
  final IconData icon;
  final bool isDark;
  final String currency;
  final double price;
  final int guests;
  final String? bookingId;
  final String? footerText;
  final bool showCheckIn;
  final bool showMore;
  final VoidCallback? onViewDetails;
  final VoidCallback? onReview;
  final VoidCallback? onCancel;

  const BookingCard({
    super.key,
    required this.title,
    required this.date,
    required this.status,
    required this.statusColor,
    required this.icon,
    required this.isDark,
    required this.currency,
    required this.price,
    this.guests = 1,
    this.bookingId,
    this.footerText,
    this.showCheckIn = false,
    this.showMore = false,
    this.onViewDetails,
    this.onReview,
    this.onCancel,
  });

  String get _formattedPrice {
    if (currency == 'USD') return '\$${price.toStringAsFixed(0)}';
    if (currency == 'JOD') return '${(price * 0.71).toStringAsFixed(0)} JOD';
    if (currency == 'EUR') return '€${(price * 0.92).toStringAsFixed(0)}';
    return '\$${price.toStringAsFixed(0)}';
  }

  String get _formattedDate {
    try {
      final DateTime parsed = DateTime.parse(date);
      return '${parsed.year}-${parsed.month.toString().padLeft(2, '0')}-${parsed.day.toString().padLeft(2, '0')}';
    } catch (_) {
      return date.length > 10 ? date.substring(0, 10) : date;
    }
  }

