const test = require("node:test");
const assert = require("node:assert/strict");
const { ApiError, validateRecommendationBody } = require("../src/http/validation");
const { classifyScope } = require("../src/services/scopeService");
const { createAdvisorService } = require("../src/services/advisorService");

const rejects = (body, code) => {
    assert.throws(() => validateRecommendationBody(body), (error) => {
        assert.ok(error instanceof ApiError, "must be an ApiError");
        assert.equal(error.statusCode, 400);
        if (code) assert.equal(error.code, code);
        return true;
    });
};

// ---------------------------------------------------------------- body shape

test("accepts a minimal valid request and trims the query", () => {
    const result = validateRecommendationBody({ query: "  a cultural trip to Petra  " });
    assert.equal(result.query, "a cultural trip to Petra");
    assert.equal(result.conversationId, undefined);
});

test("rejects a body that is not a JSON object", () => {
    for (const body of [null, undefined, "query", 42, true, []]) rejects(body, "INVALID_BODY");
});

test("rejects any field the contract does not define", () => {
    rejects({ query: "a trip to Petra", admin: true }, "UNKNOWN_FIELDS");
    rejects({ query: "a trip to Petra", databaseUri: "mongodb://x" }, "UNKNOWN_FIELDS");
    rejects({ query: "a trip to Petra", $where: "1" }, "UNKNOWN_FIELDS");
});

test("names the unknown fields so the caller can fix the request", () => {
    assert.throws(() => validateRecommendationBody({ query: "a trip", a: 1, b: 2 }), (error) => {
        assert.deepEqual(error.fields.unknown, ["a", "b"]);
        assert.match(error.message, /a, b/);
        return true;
    });
});

// ---------------------------------------------------------------- query

test("rejects a non-string query", () => {
    for (const query of [42, null, undefined, {}, [], true]) rejects({ query }, "INVALID_QUERY");
});

test("enforces the 2 to 1000 character bound", () => {
    rejects({ query: "a" }, "INVALID_QUERY");
    rejects({ query: "   " }, "INVALID_QUERY");
    rejects({ query: "x".repeat(1001) }, "INVALID_QUERY");
    assert.equal(validateRecommendationBody({ query: "hi" }).query, "hi");
    assert.equal(validateRecommendationBody({ query: "x".repeat(1000) }).query.length, 1000);
});

test("measures length after trimming, not before", () => {
    rejects({ query: `  a${" ".repeat(50)}` }, "INVALID_QUERY");
});

test("rejects control characters that could corrupt a downstream log or prompt", () => {
    for (const query of ["Petra�trip", "Petratrip", "Petratrip"]) {
        rejects({ query }, "INVALID_QUERY");
    }
});

test("normalises compatibility forms so equivalent queries behave alike", () => {
    // NFKC folds the full-width characters some mobile keyboards produce.
    assert.equal(validateRecommendationBody({ query: "Ｐｅｔｒａ" }).query, "Petra");
});

test("accepts Arabic queries unchanged", () => {
    const query = "أريد رحلة عائلية إلى البتراء";
    assert.equal(validateRecommendationBody({ query }).query, query);
});

// ---------------------------------------------------------------- conversation id

test("accepts a well-formed conversation id", () => {
    const conversationId = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
    assert.equal(validateRecommendationBody({ query: "cheaper please", conversationId }).conversationId, conversationId);
});

test("rejects a malformed conversation id", () => {
    for (const conversationId of ["not-an-id", "12345", "aaaaaaaa-aaaa", "'; DROP TABLE packages; --", "a".repeat(80)]) {
        rejects({ query: "cheaper please", conversationId }, "INVALID_CONVERSATION_ID");
    }
});

test("rejects a conversation id that is not a string", () => {
    for (const conversationId of [42, {}, [], true]) {
        rejects({ query: "cheaper please", conversationId }, "INVALID_CONVERSATION_ID");
    }
});

test("treats an explicitly null conversation id as absent", () => {
    assert.equal(validateRecommendationBody({ query: "a trip", conversationId: null }).conversationId, null);
});

test("the rejection tells the caller where a valid id comes from", () => {
    assert.throws(() => validateRecommendationBody({ query: "a trip", conversationId: "nope" }), (error) => {
        assert.match(error.fields.conversationId, /returned by this API/);
        return true;
    });
});

// ---------------------------------------------------------------- scope classification

test("greetings are answered with the capability statement, not a package search", () => {
    for (const greeting of ["hi", "Hello", "hey!", "مرحبا", "السلام عليكم", "hola", "bonjour"]) {
        assert.equal(classifyScope(greeting), "capabilities", `greeting: ${greeting}`);
    }
});

test("a greeting embedded in a real request is not treated as a bare greeting", () => {
    assert.equal(classifyScope("hi, find me a cultural package in Petra"), "package_search");
});

test("a follow-up is understood as a package search once a conversation exists", () => {
    assert.equal(classifyScope("cheaper", false), "out_of_scope");
    assert.equal(classifyScope("cheaper", true), "package_search");
});

test("an explanation request only resolves once there is something to explain", () => {
    for (const query of ["why?", "why that one?", "explain", "how did you choose", "لماذا", "pourquoi"]) {
        assert.equal(classifyScope(query, true), "explain_recommendation", `explanation: ${query}`);
        assert.notEqual(classifyScope(query, false), "explain_recommendation", `no history: ${query}`);
    }
});

test("the explanation pattern is anchored, so a longer question is searched rather than explained", () => {
    // Deliberate: anchoring avoids classifying "why is Petra expensive" as an
    // explanation request. The cost is that verbose phrasing falls through to
    // a package search, which still answers from stored data.
    assert.equal(classifyScope("why did you pick that one?", true), "package_search");
});

// ---------------------------------------------------------------- lost context

test("a follow-up whose stored context has expired is answered honestly", async () => {
    const advisor = createAdvisorService({
        config: { currency: "JOD" },
        preferences: { extract: () => ({}) },
        currency: { convert: async () => null },
        weather: { forecast: async () => ({ available: false }) },
        packages: { findCandidates: async () => { throw new Error("must not query packages"); } }
    });

    const response = await advisor.recommend("cheaper", { contextLost: true });
    assert.equal(response.outcome, "context_lost");
    assert.match(response.reply, /no longer have the earlier part/i);
    assert.ok(response.suggestions.length >= 3, "the customer is told how to restate the request");
    assert.deepEqual(response.matchingPackages ?? [], []);
});

test("a lost-context marker does not hijack a self-contained new question", async () => {
    let queried = false;
    const advisor = createAdvisorService({
        config: { currency: "JOD" },
        preferences: { extract: () => ({ people: 2 }) },
        currency: { convert: async () => null },
        weather: { forecast: async () => ({ available: false }) },
        packages: { findCandidates: async () => { queried = true; return []; } },
        knowledge: { findAll: async () => [] }
    });

    const response = await advisor.recommend("find a cultural package in Petra for 2 people", { contextLost: true });
    assert.notEqual(response.outcome, "context_lost");
    assert.equal(queried, true, "a complete request is searched even when earlier context was lost");
});

