const mongoose = require("mongoose");
const { v7: uuidv7 } = require("uuid");
const { MongooseStandardDate } = require("../utils/dateFormatter");
const softDeletePlugin = require("../utils/softDeletePlugin");

const BookingSchema = new mongoose.Schema({
    _id: {
        type: mongoose.Schema.Types.UUID,
        default: uuidv7,
    },
    user_id: {
        type: mongoose.Schema.Types.UUID,
        required: true,
        ref: "User"
    },
    vendor_id: {
        type: mongoose.Schema.Types.UUID,
        required: true,
        ref: "Vendor"
    },
    package_id: {
        type: mongoose.Schema.Types.UUID,
        required: true,
        ref: "Package"
    },
    booking_date: {
        type: Date,
        required: true
    },
    number_of_people: {
        type: Number,
        min: [1, "Number of people must be at least 1"],
        max: [5, "Number of people must be at most 5"],
        required: true
    },
    creator_role: {
        type: String,
        enum: ["user", "vendor"],
        required: true
    },
    booked_by: {
        type: mongoose.Schema.Types.UUID,
        ref: "User",
        default: null
    },
    booking_source: {
        type: String,
        enum: ['CustomerApp', 'VendorDashboard'],
        default: 'CustomerApp'
    },
    status: {
        type: String,
        required: true,
        enum: ["pending_payment", "pending", "accepted", "rejected", "completed", "cancelled"], // 🌟 إضافة pending_payment
        default: "pending_payment"
    },
    payment_deadline: {
        type: Date,
        default: function() {
            return new Date(Date.now() + 1 * 60 * 60 * 1000); // المهلة أصبحت ساعة واحدة
        }
    },
    total_price: {
        type: Number,
        required: true,
        min: [0, "Total price cannot be negative"]
    },
    cancelled_by: {
        type: mongoose.Schema.Types.UUID,
        ref: "User",
        default: null
    },
    status_history: [{
        status: { type: String },
        changed_by: { type: mongoose.Schema.Types.UUID, ref: "User" },
        changed_at: { type: Date, default: Date.now },
        note: { type: String }
    }],
    deletionRequestedAt: {
        ...MongooseStandardDate,
        default: null
    }
}, {
    timestamps: true,
    strict: 'throw', 
    versionKey: false,
    toJSON: { getters: true, virtuals: true },
    toObject: { getters: true, virtuals: true }
});

BookingSchema.virtual('booking_time_formatted').get(function() {
    if (!this.createdAt) return null;
    
    const date = new Date(this.createdAt);
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    
    return `${hours}:${minutes}`;
});

BookingSchema.virtual('booking_date_formatted').get(function() {
    if (!this.createdAt) return null;
    
    const date = new Date(this.createdAt);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    
    return `${year}-${month}-${day}`;
});

BookingSchema.plugin(softDeletePlugin);
module.exports = mongoose.model("Booking", BookingSchema);

// models/BookingPayment.js
const mongoose = require("mongoose");
const { v7: uuidv7 } = require("uuid");
const softDeletePlugin = require("../utils/softDeletePlugin");

const bookingPaymentSchema = new mongoose.Schema({
    _id: {
        type: mongoose.Schema.Types.UUID,
        default: uuidv7,
    },
    user_id: {
        type: mongoose.Schema.Types.UUID,
        ref: "User",
        required: true,
    },
    vendor_id: {
        type: mongoose.Schema.Types.UUID,
        ref: "Vendor",
        required: true,
    },
    booking_id: {
        type: mongoose.Schema.Types.UUID,
        ref: "Booking",
        required: true,
    },
    amount: {
        type: Number,
        required: true,
    },
    currency: {
        type: String,
        default: 'JOD', 
    },
    payment_method: {
        type: String,
        enum: ['CliQ', 'Cash', 'ManualBankTransfer', 'OnlineGateway'], 
        required: true,
    },
    payment_status: {
        type: String,
        enum: ['Pending', 'Verified', 'Rejected', 'Failed', 'Cancelled'], 
        default: 'Pending',
        required: true,
    },
    receipt_image: {
        url: { 
            type: String, 
            required: function() { 
                return this.payment_method === 'CliQ';
            }
        },
        public_id: { 
            type: String, 
            required: function() { 
                return this.payment_method === 'CliQ';
            }
        }
    },
    transaction_id: {
        type: String,
        required: function() { return this.payment_method === 'OnlineGateway'; }
    },
    payment_description: {
        type: String, 
        required: true,
    },
    verified_by: {
        type: mongoose.Schema.Types.UUID,
        ref: "Employee", 
        required: false,
    },
    verified_at: {
        type: Date,
        required: false,
    },
    rejection_reason: {
        type: String,
        required: function() { return this.payment_status === 'Rejected'; }
    },
    // 🌟 حقول الـ Soft Delete
    deleted_by: {
        type: mongoose.Schema.Types.UUID,
        ref: "User",
        default: null
    },
    deleted_at: {
        type: Date,
        default: null
    },
    payment_metadata: {
        type: Object,
        default: {},
    }
}, { timestamps: true,
    strict: 'throw',
    versionKey: false,});

bookingPaymentSchema.plugin(softDeletePlugin);
module.exports = mongoose.model("BookingPayment", bookingPaymentSchema);

