exports.verifyOtp = async (req, res, next) => {
   try { 
        const { email, otp, purpose } = req.body;
        const verificationPurpose = purpose || 'registration';

        await verifyOtpCore({
            email: email, 
            otp: otp,
            purpose: verificationPurpose
