const jwt = require("jsonwebtoken");
const User = require("../Models/UserModel");
const AppError = require("../utils/AppError");
const { checkRole } = require("../utils/checkvalidete");
const Vendor = require("../Models/VendorModel");


exports.protect = async (req, res, next) => {
    try {
        let token;
        if (req.headers.authorization && req.headers.authorization.startsWith("Bearer")) {
            token = req.headers.authorization.split(" ")[1];
        }

        if (!token) {
            return next(new AppError("You are not logged in! Please log in to get access.", 401));
        }

        let decoded;
        try {
            decoded = jwt.verify(token, process.env.JWT_SECRET);
        } catch (err) {
            return next(new AppError("Invalid token. Please log in again!", 401));
        }

        let currentUser;

        if (checkRole(decoded.role, ["vendor"])) {
            // decoded.id is the User ID, so we need to find the Vendor by owner_user_id
            currentUser = await Vendor.findOne({ owner_user_id: decoded.id });
            if (!currentUser) {
                // Fallback in case decoded.id was actually the Vendor ID
                currentUser = await Vendor.findById(decoded.id);
            }
        } else {
            currentUser = await User.findById(decoded.id);
        }

        if (!currentUser) {
            return next(new AppError("The user belonging to this token no longer exists.", 401));
        }

        // Attach user to request
        req.user = currentUser;
        req.user.role = decoded.role; // Ensure role is available for checkRole function
        next();
    } catch (error) {
        next(error);
    }
};

exports.restrictTo = (...roles) => {
    return (req, res, next) => {
        if (!checkRole(req.user.role, roles)) {
            return next(new AppError("You do not have permission to perform this action", 403));
        }
        next();
    };
};

const NodeCache = require("node-cache");

// Standard cache (TTL 5 minutes by default)
// We set checkperiod to automatically clear expired items
const cache = new NodeCache({ stdTTL: 300, checkperiod: 320 });

/**
 * Middleware to cache HTTP responses
 * @param {number} duration - Time to live in seconds
 */
const cacheMiddleware = (duration) => {
    return (req, res, next) => {
        if (req.method !== "GET") {
            return next();
        }

        // Use the request URL as the cache key
        const key = req.originalUrl;
        const cachedResponse = cache.get(key);

        if (cachedResponse) {
            console.log(`[Cache] HIT for key: ${key}`);
            return res.json(cachedResponse);
        }

        console.log(`[Cache] MISS for key: ${key}`);
        
        // Override res.json to capture the response before sending it
        const originalJson = res.json;
        res.json = (body) => {
            // Only cache successful responses
            if (res.statusCode >= 200 && res.statusCode < 300) {
                let cacheableBody = body;
                try {
                    cacheableBody = JSON.parse(JSON.stringify(body));
                } catch(e) {}
                cache.set(key, cacheableBody, duration);
            }
            // Call the original res.json
            return originalJson.call(res, body);
        };

        next();
    };
};

/**
 * Helper to clear cache manually if needed (e.g., when a package is created/updated)
 * @param {string} keyPattern - The start of the URL to clear (e.g., "/api/v1/packages")
 */
const clearCache = (keyPattern) => {
    const keys = cache.keys();
    const keysToDelete = keys.filter(key => key.startsWith(keyPattern));
    if (keysToDelete.length > 0) {
        cache.del(keysToDelete);
        console.log(`[Cache] Cleared keys: ${keysToDelete.join(', ')}`);
    }
};

module.exports = {
    cacheMiddleware,
    clearCache
};

