const mongoose = require("mongoose");
const AppError = require('../../../utils/AppError');
const sharp = require('sharp');
const APIFeatures = require('../../../utils/apiFeatures');
const Package = require('../../../Models/PackageModel');
const PackageDetails = require('../../../Models/packageDetailsModels'); // 🌟 استيراد جدول التفاصيل
const FileStorageService = require("../../Integration/FileStorageService");
const { checkRole } = require("../../../utils/checkvalidete");

// ==========================================
// 🛡️ HELPER: Check Package Ownership
// ==========================================
const checkPackageOwnership = (userOrVendor, packageDoc) => {
    if (checkRole(userOrVendor.role, ["admin"])) return true;
    if (checkRole(userOrVendor.role, ["vendor"])) {
        const vendorId = packageDoc.vendor_id && packageDoc.vendor_id._id
            ? packageDoc.vendor_id._id.toString()
            : (packageDoc.vendor_id ? packageDoc.vendor_id.toString() : null);

        // Allow if it matches Vendor ID, OR if it matches the Vendor's Owner (User) ID
        if (vendorId !== userOrVendor._id.toString() && vendorId !== userOrVendor.owner_user_id?.toString()) {
            console.log("OWNERSHIP FAILED!");
            console.log("Package vendorId:", vendorId);
            console.log("userOrVendor._id:", userOrVendor._id.toString());
            console.log("userOrVendor.owner_user_id:", userOrVendor.owner_user_id?.toString());
            throw new AppError("You do not have permission to modify or delete this package", 403);
        }
    } else {
        throw new AppError("Only vendors or admins can manage packages", 403);
    }
};

// ==========================================
// 1. CORE: Get All Packages (خفيفة وسريعة للواجهة)
// ==========================================
exports.getAllPackagesCore = async function (queryString) {
    try {
        const baseFilter = { startDate: { $gt: new Date() } };

        // 1. Prepare filter for countDocuments (to include package_type and other filters)
        const queryObj = { ...queryString };
        const excludedFields = ['page', 'sort', 'limit', 'fields', 'keyword', 'search'];
        excludedFields.forEach(el => delete queryObj[el]);
        let queryStr = JSON.stringify(queryObj);
        queryStr = queryStr.replace(/\b(gte|gt|lte|lt)\b/g, match => `$${match}`);
        const finalFilter = { ...baseFilter, ...JSON.parse(queryStr) };

        // 🔍 Add Search Functionality by Package Name
        if (queryString.keyword || queryString.search) {
            const searchTerm = queryString.keyword || queryString.search;
            finalFilter.package_name = { $regex: searchTerm, $options: 'i' };
        }

        // 2. Count total documents matching the filters (before pagination)
        const totalDocuments = await Package.countDocuments(finalFilter);

        // 3. Apply features (filter, sort, select, paginate)
        const baseQuery = Package.find(baseFilter).populate({
            path: 'vendor_id',
            select: 'vendor_company_name owner_user_id',
            populate: {
                path: 'owner_user_id',
                match: { role: 'vendor' },
                select: 'name email mobileNumber role -_id',
                strictPopulate: false
            }
        });

        const features = new APIFeatures(baseQuery, queryString)
            .filter()
            .sort()
            .limitFields()
            .paginate();

        const packages = await features.query;

        // 4. Calculate pagination metadata
        const page = parseInt(queryString.page, 10) || 1;
        const limit = parseInt(queryString.limit, 10) || 15;
        const totalPages = Math.ceil(totalDocuments / limit);

        console.log("PACKAGES FETCHED SUCCESSFULLY, COUNT:", packages.length);
        return {
            count: packages.length,
            pagination: {
                currentPage: page,
                limit: limit,
                totalPages: totalPages,
                totalDocuments: totalDocuments,
                hasNextPage: page < totalPages,
                hasPrevPage: page > 1,
                nextPage: page < totalPages ? page + 1 : null,
                prevPage: page > 1 ? page - 1 : null
            },
            data: packages
        };
    } catch (error) {
        if (error.name === 'CastError') {
            console.error("CAST ERROR ON PATH:", error.path);
            throw new AppError(`Invalid value for path: ${error.path}`, 400);
        }
        if (error.statusCode) throw error;
        throw new AppError(error.message || "Unknown error", 500);
    }
};

// ==========================================
// 2. CORE: Get Single Package (مع التفاصيل الكاملة)
// ==========================================
exports.getPackageCore = async function (packageId, queryString = {}) {
    try {
        let query = Package.findOne({ _id: packageId })
            .populate({
                path: 'vendor_id',
                select: 'vendor_company_name owner_user_id',
                populate: {
                    path: 'owner_user_id',
                    match: { role: 'vendor' },
                    select: 'name email mobileNumber role -_id',
                    strictPopulate: false
                }
            })
            .populate('details'); // 🌟 السحر هنا: جلب كل التفاصيل من الجدول الآخر

        if (queryString.fields) {
            const fields = queryString.fields.split(',').join(' ');
            query = query.select(fields);
        } else {
            query = query.select('-__v');
        }

        const packageDoc = await query;

        if (!packageDoc) {
            throw new AppError('The package is not found or has been deleted', 404);
        }

        return packageDoc;
    } catch (error) {
        if (error.statusCode) throw error;
        throw new AppError(error.message, 500);
    }
};

// ==========================================
// 3. CORE: Create Package (مع الـ Transactions)
// ==========================================
exports.createPackageCore = async function (user, packageData, file) {
    let uploadedImagePublicId = null; // للتنظيف في حال الفشل
    const session = await mongoose.startSession();
    session.startTransaction();

    try {
        if (!checkRole(user.role, ["vendor", "admin"])) {
            throw new AppError("Only vendors and admins can create packages. You are logged in as a regular user.", 403);
        }

        const secureVendorId = user._id;
        const vendorName = user.vendor_company_name || user.name || 'Vendor';

        if (!file) throw new AppError("Package image is required", 400);

        const activePackageExists = await Package.findOne({
            package_name: packageData.package_name,
            vendor_id: secureVendorId,
            package_status: 'active',
            isDeleted: { $ne: true }
        }).session(session);

        if (activePackageExists) {
            throw new AppError(`You cannot create this package. You already have an ACTIVE package named "${packageData.package_name}".`, 409);
        }

        // 🌟 1. رفع الصورة
        const optimizedBuffer = await sharp(file.buffer)
            .resize(800, 800, { fit: 'inside', withoutEnlargement: true })
            .webp({ quality: 80 })
            .toBuffer();

        const safeCompanyName = vendorName.replace(/[^a-zA-Z0-9]/g, '_');
        const safePackageName = packageData.package_name.replace(/[^a-zA-Z0-9]/g, '_');
        const today = new Date();
        const formattedDate = `${String(today.getDate()).padStart(2, '0')}-${String(today.getMonth() + 1).padStart(2, '0')}-${today.getFullYear()}`;
        const uploadPath = `xenon/packages/vendor/${safeCompanyName}/${safePackageName}/${safePackageName}_${formattedDate}`;
        const uploadResult = await FileStorageService.uploadImageFromBuffer(optimizedBuffer, uploadPath);

        uploadedImagePublicId = uploadResult.public_id;

        // 🌟 2. إنشاء الباقة الأساسية
        const newPackage = await Package.create([{
            vendor_id: secureVendorId,
            package_name: packageData.package_name,
            package_price: packageData.package_price,
            package_description: packageData.package_description,
            startDate: packageData.startDate,
            endDate: packageData.endDate,
            max_people: packageData.max_people,
            images: [{
                url: uploadResult.secure_url,
                public_id: uploadResult.public_id
            }],
            package_type: packageData.package_type ? packageData.package_type.toLowerCase() : packageData.package_type,
            package_status: packageData.package_status || 'active'
        }], { session });

        // 🌟 3. إنشاء تفاصيل الباقة وربطها
        await PackageDetails.create([{
            package_id: newPackage[0]._id, // الربط الوثيق
            itinerary: packageData.itinerary,
            included_services: packageData.included_services,
            excluded_services: packageData.excluded_services,
            meeting_point: packageData.meeting_point,
            location_coordinates: packageData.location_coordinates,
            cancellation_policy: packageData.cancellation_policy,
            important_notes: packageData.important_notes
        }], { session });

        await session.commitTransaction();
        session.endSession();

        return newPackage[0];
    } catch (error) {
        await session.abortTransaction();
        session.endSession();

        // 🌟🌟 هندسة الطوارئ (Emergency Cleanup)
        if (uploadedImagePublicId) {
            await FileStorageService.deleteImage(uploadedImagePublicId).catch(e => console.error("Cloud cleanup failed:", e));
        }

        if (error.statusCode) throw error;
        throw new AppError(error.message, 500);
    }
};

// ==========================================
// 4. CORE: Update Package (تحديث الجدولين)
// ==========================================
exports.updatePackageCore = async function (userOrVendor, packageId, updateData, file) {
    let newUploadedImageId = null;
    let oldImagesToDelete = [];
    const session = await mongoose.startSession();
    session.startTransaction();

    try {
        const existingPackage = await Package.findById(packageId).session(session);
        if (!existingPackage) {
            throw new AppError('This package is not found', 404);
        }

        checkPackageOwnership(userOrVendor, existingPackage);

        const packageUpdates = {};
        const detailsUpdates = {};

        // 1. Date Logic Validation
        const finalStartDate = updateData.startDate || existingPackage.startDate;
        const finalEndDate = updateData.endDate || existingPackage.endDate;
        if (finalStartDate && finalEndDate && new Date(finalStartDate) >= new Date(finalEndDate)) {
            throw new AppError("The end date cannot be before or equal to the start date", 400);
        }

        // 2. فصل البيانات: Package vs PackageDetails
        const packageFields = ['startDate', 'endDate', 'package_name', 'package_price', 'package_description', 'package_type', 'package_status'];
        const detailsFields = ['itinerary', 'included_services', 'excluded_services', 'meeting_point', 'location_coordinates', 'cancellation_policy', 'important_notes'];

        packageFields.forEach(field => {
            if (updateData[field] !== undefined) packageUpdates[field] = updateData[field];
        });

        detailsFields.forEach(field => {
            if (updateData[field] !== undefined) detailsUpdates[field] = updateData[field];
        });

        // 3. Smart Capacity Management
        if (updateData.max_people !== undefined && updateData.max_people !== existingPackage.max_people) {
            const newMax = parseInt(updateData.max_people, 10);
            const capacityDifference = newMax - existingPackage.max_people;
            const newAvailableSeats = existingPackage.available_seats + capacityDifference;

            if (newAvailableSeats < 0) {
                throw new AppError(`Cannot reduce max_people to ${newMax}. Existing bookings exceed this limit.`, 400);
            }
            packageUpdates.max_people = newMax;
            packageUpdates.available_seats = newAvailableSeats;
        }

        // 4. Safe Cloud Storage Update
        if (file) {
            const safeCompanyName = (userOrVendor.vendor_company_name || userOrVendor.company_name || userOrVendor.name || 'Vendor').replace(/[^a-zA-Z0-9]/g, '_');
            const safePackageName = (packageUpdates.package_name || existingPackage.package_name).replace(/[^a-zA-Z0-9]/g, '_');

            const optimizedBuffer = await sharp(file.buffer)
                .resize(800, 800, { fit: 'inside', withoutEnlargement: true })
                .webp({ quality: 80 })
                .toBuffer();

            const today = new Date();
            const formattedDate = `${String(today.getDate()).padStart(2, '0')}-${String(today.getMonth() + 1).padStart(2, '0')}-${today.getFullYear()}`;
            const uploadPath = `xenon/packages/vendor/${safeCompanyName}/${safePackageName}/${safePackageName}_${formattedDate}`;
            const uploadResult = await FileStorageService.uploadImageFromBuffer(optimizedBuffer, uploadPath);

            newUploadedImageId = uploadResult.public_id;

            if (existingPackage.images && existingPackage.images.length >= 5) {
                await FileStorageService.deleteImage(newUploadedImageId);
                throw new AppError("Maximum of 5 images allowed per package. Please delete an existing image first.", 400);
            }

            packageUpdates.images = [
                ...(existingPackage.images || []),
                {
                    url: uploadResult.secure_url,
                    public_id: uploadResult.public_id
                }
            ];
        }

        if (Object.keys(packageUpdates).length === 0 && Object.keys(detailsUpdates).length === 0) {
            throw new AppError('No valid data provided for update', 400);
        }

        // 🌟 5. تحديث الداتابيز (الجدولين)
        let updatedPackage = existingPackage;

        if (Object.keys(packageUpdates).length > 0) {
            updatedPackage = await Package.findByIdAndUpdate(packageId, { $set: packageUpdates }, { new: true, runValidators: true, session });
        }

        if (Object.keys(detailsUpdates).length > 0) {
            // تحديث التفاصيل إن وجدت
            await PackageDetails.findOneAndUpdate(
                { package_id: packageId },
                { $set: detailsUpdates },
                { new: true, runValidators: true, session }
            );
        }

        await session.commitTransaction();
        session.endSession();

        if (oldImagesToDelete.length > 0) {
            for (const image of oldImagesToDelete) {
                await FileStorageService.deleteImage(image.public_id).catch(e => console.error("Cloud cleanup failed:", e));
            }
        }

        return updatedPackage;
    } catch (error) {
        await session.abortTransaction();
        session.endSession();

        if (newUploadedImageId) {
            await FileStorageService.deleteImage(newUploadedImageId).catch(e => console.error("Cloud cleanup failed:", e));
        }

        if (error.statusCode) throw error;
        throw new AppError(error.message, 500);
    }
};

// ==========================================
// 5. CORE: Delete Package (Soft Delete)
// ==========================================
exports.deletePackageCore = async function (userOrVendor, packageId) {
    try {
        const packageDoc = await Package.findById(packageId);

        if (!packageDoc) {
            throw new AppError('The package is not found', 404);
        }

        checkPackageOwnership(userOrVendor, packageDoc);

        // 🌟 تطبيق طلب العميل: إذا كانت active، نجعلها inactive فقط.
        if (packageDoc.package_status === 'active') {
            packageDoc.package_status = 'inactive';
            await packageDoc.save();
            await PackageDetails.updateOne({ package_id: packageId }, { $set: { package_status: 'inactive' } });
            return { message: "The package was active, so it has been deactivated instead of permanently deleted." };
        }

        // إذا كانت inactive بالفعل، يتم الحذف الوهمي (Soft Delete)
        packageDoc.isDeleted = true;
        packageDoc.deletionRequestedAt = new Date();

        await packageDoc.save();
        return { message: "Package deleted successfully" };
    } catch (error) {
        if (error.statusCode) throw error;
        throw new AppError(error.message, 500);
    }
};

const mongoose = require("mongoose");
const User = require("../../Models/UserModel");
const Booking = require("../../Models/BookingModel"); 
const Report = require("../../Models/ReportsModels");
const Complaint = require("../../Models/ComplaintModel");
const Package = require("../../Models/PackageModel");
const Review = require("../../Models/ReviewModel"); 
const AppError = require("../../utils/AppError");

const buildDateFilter = (startDate, endDate) => {
    const dateQuery = {};
    if (startDate || endDate) {
        dateQuery.createdAt = {};
        if (startDate) dateQuery.createdAt.$gte = new Date(startDate);
        if (endDate) dateQuery.createdAt.$lte = new Date(endDate);
    }
    return dateQuery;
};

const getTrafficVolume = async (startDate, endDate) => {
    return await Booking.countDocuments(buildDateFilter(startDate, endDate));
};

const getDemographics = async (startDate, endDate) => {
    return await User.aggregate([
        { $match: buildDateFilter(startDate, endDate) },
        { $group: { _id: "$role", count: { $sum: 1 } } },
        { $project: { role: "$_id", count: 1, _id: 0 } }
    ]);
};

const getModerationEfficiency = async (startDate, endDate) => {
    const stats = await Report.aggregate([
        { $match: buildDateFilter(startDate, endDate) },
        { $group: { _id: "$status", count: { $sum: 1 } } },
        { $project: { status: "$_id", count: 1, _id: 0 } }
    ]);
    return {
        total_reports: stats.reduce((acc, curr) => acc + curr.count, 0),
        breakdown: stats
    };
};

const getActiveDestinations = async (startDate, endDate) => {
    return await Booking.aggregate([
        { $match: buildDateFilter(startDate, endDate) },
        { $group: { _id: "$package_id", totalBookings: { $sum: 1 } } },
        { $sort: { totalBookings: -1 } },
        { $limit: 5 },
        { $lookup: { from: 'packages', localField: '_id', foreignField: '_id', as: 'package_info' }},
        { $unwind: { path: "$package_info", preserveNullAndEmptyArrays: true } },
        { $project: { package_id: "$_id", total_bookings: "$totalBookings", package_name: "$package_info.title", _id: 0 } }
    ]);
};

const getAdminActualRevenueCore = async (startDate, endDate) => {
    const COMMISSION_RATE = 0.10; 
    const revenueStats = await Booking.aggregate([
        { 
            $match: { 
                status: { $in: ["completed", "accepted"] },
                payment_status: "paid",
                ...buildDateFilter(startDate, endDate)
            } 
        },
        { $group: { _id: null, totalPlatformSales: { $sum: "$total_price" }, totalSuccessfulBookings: { $sum: 1 } } },
        { $project: { _id: 0, totalSuccessfulBookings: 1, totalPlatformSales: 1, adminActualRevenue: { $multiply: ["$totalPlatformSales", COMMISSION_RATE] } } }
    ]);
    return revenueStats.length > 0 ? revenueStats[0] : { totalSuccessfulBookings: 0, totalPlatformSales: 0, adminActualRevenue: 0 };
};

const getAdminRevenue = async (startDate, endDate) => {
    const matchStage = { status: { $in: ['completed', 'accepted'] }, ...buildDateFilter(startDate, endDate) };
    const revenue = await Booking.aggregate([
        { $match: matchStage },
        { $group: { _id: null, total_revenue: { $sum: "$total_price" } } } 
    ]);
    return revenue.length > 0 ? revenue[0].total_revenue : 0;
};

const getVendorBookingsStatus = async (vendorId, startDate, endDate) => {
    return await Booking.aggregate([
        { $match: { vendor_id: vendorId, ...buildDateFilter(startDate, endDate) } },
        { $group: { _id: "$status", count: { $sum: 1 } } },
        { $project: { status: "$_id", count: 1, _id: 0 } }
    ]);
};

const getVendorCapacityLimits = async (vendorId, startDate, endDate) => {
    return await Package.aggregate([
        { $match: { vendor_id: vendorId, isDeleted: { $ne: true }, ...buildDateFilter(startDate, endDate) } },
        { $lookup: { 
            from: 'bookings', let: { pkgId: '$_id' },
            pipeline: [
                { $match: { $expr: { $eq: ['$package_id', '$$pkgId'] }, status: { $in: ['accepted', 'completed'] } } },
                { $group: { _id: null, total_pax: { $sum: '$number_of_people' } } } 
            ], as: 'booking_data'
        }},
        { $unwind: { path: "$booking_data", preserveNullAndEmptyArrays: true } },
        { $project: { _id: 0, package_name: "$title", max_capacity: "$max_people", booked_seats: { $ifNull: ["$booking_data.total_pax", 0] },
            occupancy_percentage: {
                $cond: [ { $gt: ["$max_people", 0] }, { $round: [ { $multiply: [ { $divide: [ { $ifNull: ["$booking_data.total_pax", 0] }, "$max_people" ] }, 100 ] }, 1 ] }, 0 ]
            }
        }}
    ]);
};

const getVendorQualityScore = async (vendorId, startDate, endDate) => {
    const matchStage = { vendor_id: vendorId, ...buildDateFilter(startDate, endDate) };
    const [complaintsCount, ratingStats] = await Promise.all([
        Complaint.countDocuments(matchStage),
        Review.aggregate([
            { $match: { vendor_id: vendorId, review_status: "accepted", ...buildDateFilter(startDate, endDate) } },
            { $group: { _id: null, avg_rating: { $avg: "$review_rating" } } }
        ])
    ]);
    return { total_complaints_received: complaintsCount, average_rating: ratingStats.length > 0 ? parseFloat(ratingStats[0].avg_rating.toFixed(1)) : 0 };
};

const getVendorFinancialBreakdownCore = async (vendorId, startDate, endDate) => {
    const breakdown = await Booking.aggregate([
        { $match: { vendor_id: vendorId, ...buildDateFilter(startDate, endDate) } },
        { $group: { _id: "$status", count: { $sum: 1 }, totalAmount: { $sum: "$total_price" } } }
    ]);

    let financialSummary = { earned_revenue: 0, pending_revenue: 0, lost_revenue: 0, total_bookings: 0 };
    breakdown.forEach(item => {
        financialSummary.total_bookings += item.count;
        if (item._id === 'completed' || item._id === 'accepted') financialSummary.earned_revenue += item.totalAmount;
        else if (item._id === 'pending') financialSummary.pending_revenue += item.totalAmount;
        else if (item._id === 'cancelled' || item._id === 'rejected') financialSummary.lost_revenue += item.totalAmount;
    });
    return financialSummary;
};

const getVendorRevenue = async (vendorId, startDate, endDate) => {
    const matchStage = { vendor_id: vendorId, status: { $in: ['completed', 'accepted'] }, ...buildDateFilter(startDate, endDate) };
    const revenue = await Booking.aggregate([
        { $match: matchStage },
        { $group: { _id: null, total_revenue: { $sum: "$total_price" } } }
    ]);
    return revenue.length > 0 ? revenue[0].total_revenue : 0;
};

const getRevenueTrendsCore = async (vendorId = null, year = new Date().getFullYear()) => {
    let matchQuery = { 
        status: { $in: ["completed", "accepted"] },
        payment_status: "paid",
        createdAt: { $gte: new Date(`${year}-01-01`), $lte: new Date(`${year}-12-31`) }
    };
    if (vendorId) matchQuery.vendor_id = vendorId;

    const trends = await Booking.aggregate([
        { $match: matchQuery },
        { $group: { _id: { $month: "$createdAt" }, monthlyRevenue: { $sum: "$total_price" }, bookingsCount: { $sum: 1 } } },
        { $sort: { "_id": 1 } }
    ]);

    const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    return months.map((month, index) => {
        const found = trends.find(t => t._id === index + 1);
        return { month: month, revenue: found ? found.monthlyRevenue : 0, bookings: found ? found.bookingsCount : 0 };
    });
};

const getCustomerRetentionCore = async (vendorId) => {
    const userBookingsCount = await Booking.aggregate([
        { $match: { vendor_id: vendorId, status: { $in: ["completed", "accepted"] } } },
        { $group: { _id: "$user_id", totalBookings: { $sum: 1 } } }
    ]);

    let analytics = { total_unique_customers: userBookingsCount.length, one_time_customers: 0, repeat_customers: 0, retention_rate: 0 };
    userBookingsCount.forEach(user => {
        if (user.totalBookings === 1) analytics.one_time_customers++;
        else analytics.repeat_customers++;
    });

    if (analytics.total_unique_customers > 0) {
        analytics.retention_rate = parseFloat(((analytics.repeat_customers / analytics.total_unique_customers) * 100).toFixed(2));
    }
    return analytics;
};

const getVendorsLeaderboardCore = async () => {
    return await Booking.aggregate([
        { $match: { status: { $in: ["completed", "accepted", "cancelled"] } } },
        { $group: {
            _id: "$vendor_id",
            totalRevenue: { $sum: { $cond: [{ $in: ["$status", ["completed", "accepted"]] }, "$total_price", 0] } },
            successfulBookings: { $sum: { $cond: [{ $in: ["$status", ["completed", "accepted"]] }, 1, 0] } },
            cancelledBookings: { $sum: { $cond: [{ $eq: ["$status", "cancelled"] }, 1, 0] } }
        }},
        { $sort: { totalRevenue: -1 } },
        { $limit: 10 },
        { $lookup: { from: 'vendors', localField: '_id', foreignField: '_id', as: 'vendor_info' } },
        { $unwind: { path: "$vendor_info", preserveNullAndEmptyArrays: true } },
        { $project: { vendor_id: "$_id", vendor_company_name: "$vendor_info.vendor_company_name", totalRevenue: 1, successfulBookings: 1, cancelledBookings: 1, _id: 0 } }
    ]);
};

const getPaymentMethodsShareCore = async (vendorId = null, startDate, endDate) => {
    let matchQuery = { payment_status: "paid", ...buildDateFilter(startDate, endDate) };
    if (vendorId) matchQuery.vendor_id = vendorId;

    const paymentShare = await Booking.aggregate([
        { $match: matchQuery },
        { $group: { _id: "$payment_method", totalAmount: { $sum: "$total_price" }, usageCount: { $sum: 1 } } },
        { $project: { method: "$_id", totalAmount: 1, usageCount: 1, _id: 0 } },
        { $sort: { usageCount: -1 } }
    ]);

    const totalTransactions = paymentShare.reduce((acc, curr) => acc + curr.usageCount, 0);
    return paymentShare.map(item => ({
        ...item,
        percentage: totalTransactions === 0 ? 0 : parseFloat(((item.usageCount / totalTransactions) * 100).toFixed(2))
    }));
};

const getPackageFinancialAnalysisCore = async (packageId, startDate, endDate) => {
    const packageStats = await Booking.aggregate([
        { $match: { package_id: packageId, ...buildDateFilter(startDate, endDate) } },
        { $group: { _id: "$status", bookingsCount: { $sum: 1 }, totalMoney: { $sum: "$total_price" } } }
    ]);

    let analysis = { package_id: packageId, success_rate: 0, total_earned: 0, total_lost_to_cancellations: 0, total_requests: 0, active_pending: 0 };
    let successfulBookings = 0;

    packageStats.forEach(stat => {
        analysis.total_requests += stat.bookingsCount;
        if (stat._id === 'completed' || stat._id === 'accepted') {
            analysis.total_earned += stat.totalMoney;
            successfulBookings += stat.bookingsCount;
        } else if (stat._id === 'cancelled' || stat._id === 'rejected') {
            analysis.total_lost_to_cancellations += stat.totalMoney;
        } else if (stat._id === 'pending') {
            analysis.active_pending += stat.totalMoney;
        }
    });

    if (analysis.total_requests > 0) analysis.success_rate = parseFloat(((successfulBookings / analysis.total_requests) * 100).toFixed(2));
    return analysis;
};

exports.getAdminDashboardCore = async function (startDate, endDate) { 
    const [traffic, demographics, moderation, destinations, grossRevenue, actualRevenue, paymentShare, leaderboard, revenueTrends] = await Promise.all([
        getTrafficVolume(startDate, endDate),
        getDemographics(startDate, endDate),
        getModerationEfficiency(startDate, endDate),
        getActiveDestinations(startDate, endDate),
        getAdminRevenue(startDate, endDate),
        getAdminActualRevenueCore(startDate, endDate),
        getPaymentMethodsShareCore(null, startDate, endDate),
        getVendorsLeaderboardCore(),
        getRevenueTrendsCore(null)   
    ]);

    return {
        financials: { gross_revenue: grossRevenue, net_profit_summary: actualRevenue, payment_methods: paymentShare },
        platform_performance: { top_destinations: destinations, vendors_leaderboard: leaderboard, revenue_trends_this_year: revenueTrends },
        platform_traffic: { total_bookings: traffic },
        demographics_overview: demographics,
        moderation_efficiency: moderation
    };
};

exports.getVendorDashboardCore = async function (vendorId, startDate, endDate) {
    if (!vendorId) throw new AppError("Vendor ID is required", 400);
    
    const [bookingsStatus, capacity, qualityScore, grossRevenue, financialBreakdown, paymentShare, customerRetention, revenueTrends] = await Promise.all([
        getVendorBookingsStatus(vendorId, startDate, endDate),
        getVendorCapacityLimits(vendorId, startDate, endDate),
        getVendorQualityScore(vendorId, startDate, endDate),
        getVendorRevenue(vendorId, startDate, endDate),
        getVendorFinancialBreakdownCore(vendorId, startDate, endDate),
        getPaymentMethodsShareCore(vendorId, startDate, endDate),
        getCustomerRetentionCore(vendorId),    
        getRevenueTrendsCore(vendorId)         
    ]);

    return {
        financials: { total_revenue: grossRevenue, breakdown: financialBreakdown, payment_methods: paymentShare, revenue_trends_this_year: revenueTrends },
        customer_insights: { retention_metrics: customerRetention },
        bookings_overview: bookingsStatus,
        capacity_management: capacity,
        quality_score: qualityScore
    };
};

exports.getTrafficVolume = getTrafficVolume;
exports.getDemographics = getDemographics;
exports.getModerationEfficiency = getModerationEfficiency;
exports.getActiveDestinations = getActiveDestinations;
exports.getAdminRevenue = getAdminRevenue;
exports.getAdminActualRevenueCore = getAdminActualRevenueCore;

exports.getVendorBookingsStatus = getVendorBookingsStatus;
exports.getVendorCapacityLimits = getVendorCapacityLimits;
exports.getVendorQualityScore = getVendorQualityScore;
exports.getVendorRevenue = getVendorRevenue;
exports.getVendorFinancialBreakdownCore = getVendorFinancialBreakdownCore;

exports.getRevenueTrendsCore = getRevenueTrendsCore;
exports.getCustomerRetentionCore = getCustomerRetentionCore;
exports.getVendorsLeaderboardCore = getVendorsLeaderboardCore;

