        if (!checkRole(user.role, ['admin', 'vendor', 'company'])) {
            throw new AppError("Unauthorized access. Admin or Vendor role required.", 403);
        }

        let query = { isDeleted: false };

        if (checkRole(user.role, ['vendor', 'company'])) {
