.otp-input { text-align:center; font-size:22px; font-weight:600; letter-spacing:.45em; font-variant-numeric:tabular-nums; }
button, input, select, textarea { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
a { color: inherit; text-decoration: none; }
button { border: 0; cursor: pointer; }

.serif { font-family: 'Source Serif 4', serif; }
.brand { color: var(--brown); font: 400 48px/1.1 'Source Serif 4', serif; letter-spacing: -1.2px; }
.primary-button {
