.primary-button:hover { transform: translateY(-1px); box-shadow: 0 8px 20px rgba(209,122,93,.25); }
.primary-button:disabled { opacity: .55; cursor: not-allowed; transform: none; }

.field { display: grid; gap: 7px; }
.field label { color: #1c1d0c; font-size: 12px; font-weight: 500; letter-spacing: .1px; }
