.field input:focus, .field select:focus { border-color: var(--clay); box-shadow: 0 0 0 3px rgba(209,122,93,.1); }
.field-hint { color: var(--muted); font-size: 11px; line-height: 1.4; }
.form-message { padding: 11px 13px; border-radius: 8px; font-size: 13px; line-height: 1.4; }
.form-message.error { color: #8e3427; background: #fff0ec; }
.form-message.success { color: #315d43; background: #eaf7ee; }

.auth-page { display: grid; grid-template-columns: 1fr 1fr; min-height: 100vh; background: white; }
.auth-panel { display: flex; justify-content: center; padding: 64px clamp(32px,7vw,96px); }
.auth-inner { width: 100%; max-width: 448px; align-self: center; }
.auth-head { margin-bottom: 42px; }
.auth-title { color: var(--brown); font: 400 32px/1.2 'Source Serif 4',serif; margin-bottom: 8px; }
.auth-subtitle { font-size: 16px; line-height: 1.6; }
.auth-image { position: relative; min-height: 720px; background: #ddd center/cover no-repeat; overflow: hidden; }
.auth-image::after { content: ''; position: absolute; inset: 0; background: linear-gradient(0deg,rgba(44,40,37,.62),transparent 55%); }
.image-quote { position: absolute; z-index: 1; left: 48px; right: 48px; bottom: 48px; color: var(--sand); }
.image-quote blockquote { font: 400 24px/1.3 'Source Serif 4',serif; }
.image-quote small { display: block; margin-top: 10px; color: #ffb68c; font-weight: 600; letter-spacing: .8px; }
.top-row { position: absolute; top: 52px; left: clamp(32px,6vw,80px); right: calc(50% + clamp(32px,6vw,80px)); z-index: 3; display: flex; justify-content: space-between; align-items: center; }
.top-actions { display:flex; align-items:center; gap:22px; }
.text-link { color: var(--clay); font-size: 14px; font-weight: 600; letter-spacing: .7px; }

.login-card { border: 1px solid rgba(218,194,182,.35); border-radius: 12px; padding: 24px; box-shadow: 0 4px 20px -4px rgba(203,153,126,.12); }
.role-tabs { display: grid; grid-template-columns: repeat(2,1fr); gap: 4px; margin-bottom: 24px; }
.role-tab { padding: 12px 6px; background: transparent; color: var(--ink); font-weight: 600; letter-spacing: .7px; border-radius: 6px; }
.role-tab.active { color: var(--brown); box-shadow: 0 2px 8px -2px rgba(203,153,126,.25); }
.form-stack { display: grid; gap: 22px; }
.label-line { display: flex; justify-content: space-between; align-items: center; }
.login-footer { margin-top: 24px; text-align: center; display:grid; gap:8px; line-height:1.5; }
.auth-separator { color:var(--line); font-size:12px; text-transform:uppercase; letter-spacing:1px; }
.legal { margin-top: 38px; color: var(--muted); font-size: 12px; opacity: .75; }

.register-panel { padding-top: 150px; }
.register-form { display: grid; gap: 19px; }
.document-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; }
.document-grid .field { min-width:0; padding:14px; border:1px solid var(--line); border-radius:8px; background:#fffdfb; }
.document-grid input[type=file] { min-height:0; padding:9px; font-size:12px; }
.registration-success { display:grid; justify-items:center; gap:18px; padding:36px 24px; border:1px solid var(--line); border-radius:14px; background:var(--sand); text-align:center; }
.registration-success svg { color:#4f7b5d; }
.registration-success h2 { color:var(--brown); font:500 26px/1.2 'Source Serif 4',serif; }
.registration-success p { max-width:560px; line-height:1.65; }
.field-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.prefix-group { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }
.prefix-option input { position: absolute; opacity: 0; pointer-events: none; }
.prefix-option span { display: block; text-align: center; padding: 10px; border: 1px solid var(--line); border-radius: 999px; }
.prefix-option input:checked + span { color: var(--clay); border-color: var(--clay); background: #f4f4f4; }
.check-line { display: flex; gap: 10px; align-items: flex-start; font-size: 14px; line-height: 1.5; }
.check-line input { accent-color: var(--clay); margin-top: 4px; }
.password-strength { display:grid; gap:9px; padding-top:2px; }
.password-strength-heading { display:flex; align-items:center; gap:10px; }
.password-strength-heading strong { min-width:68px; color:var(--muted); font-size:11px; font-weight:600; text-align:right; }
.password-meter { display:grid; grid-template-columns:repeat(6,1fr); gap:4px; flex:1; }
.password-meter span { height:4px; border-radius:99px; background:#ece7e4; transition:background .2s, transform .2s; }
.password-meter span.passed { background:#d9a087; transform:scaleY(1.12); }
.strength-strong .password-meter span.passed { background:#3d8359; }
.strength-strong .password-strength-heading strong { color:#3d8359; }
.strength-weak .password-strength-heading strong { color:#b74d3b; }
.strength-fair .password-strength-heading strong { color:#ac6b26; }
.strength-good .password-strength-heading strong { color:#7b712a; }
.password-rules { display:grid; grid-template-columns:1fr 1fr; gap:6px 12px; list-style:none; padding:10px 12px; border-radius:8px; background:#faf8f6; }
.password-rules li { display:flex; align-items:flex-start; gap:6px; font-size:11px; line-height:1.35; transition:color .2s; }
.password-rules li svg { flex:0 0 auto; margin-top:1px; }
.password-rules .missing { color:#9d5448; }
.password-rules .recommended { color:#927666; }
.password-rules .passed { color:#4d785c; }

.vendor-panel { padding-top: 150px; }
.stepper { margin-bottom: 40px; }
.stepper p { color: var(--muted); font-size: 12px; letter-spacing: .6px; margin-bottom: 12px; }
.step-track { height: 4px; border-radius: 99px; background: #f1f1f1; overflow: hidden; }
.step-track span { display: block; height: 100%; background: var(--clay); transition: width .3s; }
.vendor-actions { display: flex; align-items: center; justify-content: flex-end; gap: 12px; padding-top: 8px; }
.secondary-button { padding: 12px 18px; background: transparent; color: var(--clay); font-weight: 600; }
.input-action-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:center}.input-action-row .secondary-button{min-height:52px;border:1px solid var(--line);border-radius:8px;background:#fff}

.landing { background: white; color: var(--ink); }
.nav { position: sticky; top: 0; z-index: 10; height: 80px; padding: 0 32px; display: flex; align-items: center; justify-content: space-between; background: rgba(255,255,255,.92); backdrop-filter: blur(6px); border-bottom: 1px solid rgba(218,194,182,.3); }
.nav-links { display: flex; gap: 24px; align-items: center; color: var(--clay); font-size: 14px; font-weight: 600; letter-spacing: .7px; }
.nav-divider { width: 1px; height: 24px; background: rgba(218,194,182,.5); }
.landing-main { max-width: 1600px; margin: auto; padding: 80px 32px; }
.hero-section { min-height: 560px; display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.hero-copy { display: flex; flex-direction: column; justify-content: center; align-items: flex-start; padding-right: 80px; }
.eyebrow { color: var(--clay); font-size: 14px; font-weight: 600; letter-spacing: 1.4px; }
.hero-copy h1 { color: var(--brown); font: 600 clamp(46px,5vw,64px)/1.1 'Source Serif 4',serif; letter-spacing: -1.28px; margin: 24px 0 18px; }
.hero-copy p { max-width: 520px; font-size: 18px; line-height: 1.6; margin-bottom: 42px; }
.pill-button { border-radius: 999px; padding: 16px 32px; }
.hero-image { border-radius: 16px; background: center/cover no-repeat; box-shadow: 0 8px 30px -4px rgba(139,69,19,.15); }
.journey { margin-top: 80px; padding-bottom: 80px; }
.journey h2 { color: var(--brown); font: 500 32px/1.2 'Source Serif 4',serif; padding-bottom: 17px; border-bottom: 1px solid rgba(218,194,182,.3); margin-bottom: 48px; }
.bento { display: grid; grid-template-columns: repeat(3,1fr); grid-auto-rows: 350px; gap: 24px; }
.bento-card { position: relative; border-radius: 12px; overflow: hidden; background: #f5f5f5; padding: 48px; }
.bento-card.large { grid-column: span 2; padding: 0; }
.photo-card { color: white; background: center/cover no-repeat; }
.photo-card::after { content:''; position:absolute; inset:0; background:linear-gradient(0deg,rgba(44,40,37,.75),transparent 65%); }
.photo-content { position:absolute; z-index:1; left:48px; bottom:38px; }
.photo-content h3, .bento-card h3 { font: 500 24px/1.3 'Source Serif 4',serif; }
.photo-content p { margin-top: 8px; }
.card-kicker { display:block; margin-bottom:8px; color:#ffd2bd; font-size:11px; font-weight:600; letter-spacing:1.4px; }
.package-card { display:flex; flex-direction:column; justify-content:space-between; }
.package-icon { width:48px; height:48px; border-radius:50%; display:grid; place-items:center; background:#ffdcc6; color:var(--brown); }
.package-card h3 { color:var(--brown); }
.package-card p { margin-top:8px; line-height:1.6; }
.profile-card { background:var(--sand); border:1px solid rgba(218,194,182,.3); display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; gap:18px; }
.profile-card .avatar { width:64px; height:64px; border-radius:50%; background:#e5e5e5; display:grid; place-items:center; }
.profile-card strong { color:var(--brown); font-size:13px; letter-spacing:1.4px; }
.profile-card p { line-height:1.6; }
.footer { border-top:1px solid rgba(218,194,182,.3); padding:70px 32px; display:flex; justify-content:space-between; align-items:center; gap:30px; color:var(--brown); font-size:12px; }
.footer-links { display:flex; gap:24px; color:var(--clay); text-decoration:underline; }

/* Admin portal */
.admin-layout { min-height:100vh; display:grid; grid-template-columns:288px 1fr; background:#fff; }
.admin-sidebar { position:sticky; top:0; height:100vh; display:flex; flex-direction:column; border-right:1px solid rgba(218,194,182,.3); background:#fff; }
.admin-brand { padding:30px 24px 27px; border-bottom:1px solid rgba(218,194,182,.3); display:grid; }
.admin-brand span { color:var(--brown); font:400 39px/1 'Source Serif 4',serif; }
.admin-brand small { margin-top:8px; font-size:10px; letter-spacing:.5px; }
.admin-sidebar nav { display:grid; gap:3px; padding:22px 4px; overflow:auto; }
.admin-sidebar nav a, .admin-logout { display:flex; align-items:center; gap:14px; min-height:44px; padding:0 20px; color:var(--ink); font-size:14px; font-weight:500; }
.admin-sidebar nav a.active { color:var(--clay); background:#fbf1ec; border-right:3px solid var(--clay); }
.admin-logout { margin-top:auto; margin-bottom:18px; background:transparent; }
.admin-main { min-width:0; padding:64px clamp(28px,5vw,72px); }
.admin-header { display:flex; align-items:flex-end; justify-content:space-between; gap:24px; margin-bottom:38px; }
.admin-header h1 { color:var(--brown); font:500 32px/1.2 'Source Serif 4',serif; }
.admin-header p { max-width:680px; margin-top:8px; line-height:1.6; }
.admin-icon { width:44px; height:44px; display:grid; place-items:center; border:1px solid var(--line); border-radius:8px; color:var(--brown); background:#fff; }
.admin-search { width:270px; height:48px; display:flex; align-items:center; gap:10px; padding:0 14px; border:1px solid var(--line); border-radius:6px; color:var(--muted); }
.admin-search input { min-width:0; flex:1; border:0; outline:0; }
.admin-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:18px; margin-bottom:32px; }
.admin-kpi { min-height:170px; display:grid; align-content:start; gap:8px; padding:22px; border:1px solid rgba(218,194,182,.45); border-radius:10px; box-shadow:0 8px 24px -20px var(--brown); }
.admin-kpi svg { color:var(--clay); margin-bottom:8px; }.admin-kpi small { color:var(--muted); }.admin-kpi strong { color:var(--brown); font:500 34px 'Source Serif 4',serif; }.admin-kpi span { color:#4f7b5d; font-size:12px; }
.admin-panel { padding:28px; border:1px solid rgba(218,194,182,.45); border-radius:10px; }.admin-panel h2 { color:var(--brown); font:500 23px 'Source Serif 4',serif; margin-bottom:22px; }
.admin-modules { display:grid; grid-template-columns:repeat(3,1fr); gap:16px; }.admin-modules article { padding:20px; background:var(--sand); border-radius:8px; }.admin-modules svg { color:var(--clay); }.admin-modules b { display:block; margin:14px 0 7px; }.admin-modules p { font-size:13px; }
.admin-table-wrap { border:1px solid rgba(218,194,182,.45); border-radius:10px; overflow:auto; }.admin-table { width:100%; border-collapse:collapse; }.admin-table th { padding:16px 20px; text-align:left; color:var(--ink); font-size:11px; letter-spacing:.7px; text-transform:uppercase; background:#fffdfc; }.admin-table td { padding:20px; border-top:1px solid rgba(218,194,182,.28); font-size:14px; }
.admin-status { display:inline-flex; padding:4px 10px; border-radius:99px; background:#e7f7eb; color:#25864c; font-size:10px; font-weight:600; text-transform:uppercase; }.admin-status.pending,.admin-status.open { color:#a96600; background:#fff1cd; }.admin-status.suspended,.admin-status.inactive { color:#9f4437; background:#fde9e5; }
.admin-primary { min-height:44px; padding:0 18px; border-radius:6px; background:var(--clay); color:#fff; font-weight:600; }
.admin-data-state { margin:-20px 0 22px; padding:14px 16px; border-radius:7px; background:var(--sand); color:var(--muted); font-size:13px; }
.admin-data-state.error { background:#fff0ec; color:#8e3427; }
.admin-row-actions { display:flex; gap:8px; }.admin-row-actions button { padding:7px 11px; border:1px solid var(--line); border-radius:5px; background:#fff; color:var(--brown); }.admin-row-actions button:hover { background:var(--sand); }
.admin-chart { height:330px; display:flex; align-items:flex-end; gap:28px; padding:40px; border:1px solid rgba(218,194,182,.45); border-radius:10px; background:linear-gradient(#fff,#fffbf8); }.admin-chart div { flex:1; min-height:20px; border-radius:6px 6px 0 0; background:linear-gradient(var(--clay),var(--brown)); opacity:.86; }
@media(max-width:950px){.admin-layout{grid-template-columns:82px 1fr}.admin-brand span{font-size:22px}.admin-brand small,.admin-sidebar nav a:not(.active){font-size:0}.admin-sidebar nav a{justify-content:center;padding:0}.admin-sidebar nav a.active{font-size:0}.admin-logout{font-size:0;justify-content:center}.admin-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:650px){.admin-layout{display:block;width:100%;overflow-x:hidden}.admin-sidebar{position:static;width:100%;min-width:0;height:auto;overflow:hidden}.admin-sidebar nav{display:flex;max-width:100%;overflow-x:auto}.admin-sidebar nav a,.admin-sidebar nav a.active{min-width:55px;font-size:0;border:0}.admin-logout{display:none}.admin-main{max-width:100%;padding:30px 18px}.admin-header{align-items:flex-start;flex-direction:column}.admin-search{width:100%}.admin-grid,.admin-modules{grid-template-columns:1fr}}

@media (max-width: 850px) {
  .auth-page { grid-template-columns: 1fr; }
  .auth-image { display: none; }
  .auth-panel { min-height: 100vh; padding: 130px 28px 50px; }
  .top-row { right: 28px; left: 28px; }
  .top-actions .text-link:first-child { display:none; }
  .register-panel, .vendor-panel { padding-top: 130px; }
  .nav { padding: 0 20px; }
  .nav-links a:not(:last-child), .nav-divider { display: none; }
  .landing-main { padding: 50px 20px; }
  .hero-section { grid-template-columns: 1fr; }
  .hero-copy { padding: 0; }
  .hero-image { min-height: 420px; grid-row: 1; }
  .bento { grid-template-columns: 1fr; grid-auto-rows: 320px; }
  .bento-card.large { grid-column: auto; }
  .footer { flex-direction: column; text-align:center; }
}

@media (max-width: 520px) {
  .simple-page { padding:36px 18px; }
  .brand { font-size: 40px; }
  .field-grid { grid-template-columns: 1fr; }
  .auth-panel { padding-inline: 20px; }
  .login-card { padding: 18px; }
  .hero-image { min-height: 300px; }
  .hero-copy h1 { font-size: 44px; }
  .bento-card { padding: 30px; }
  .password-rules { grid-template-columns:1fr; }
  .document-grid { grid-template-columns:minmax(0,1fr); }
}
.loading-screen {
  position: fixed; inset: 0; z-index: 9999; display: flex; flex-direction: column;
  align-items: center; justify-content: center; overflow: hidden;
  color: var(--brown); background:
    radial-gradient(circle at 50% 42%, rgba(255,220,198,.72), transparent 24%),
    linear-gradient(145deg, #fff 0%, #f8f2ec 100%);
  animation: loading-exit .45s ease 1.05s both;
}
.loading-mark { position: relative; width: 96px; height: 96px; display: grid; place-items: center; }
.loading-x { position: relative; z-index: 2; font: 500 40px/1 'Source Serif 4',serif; animation: mark-pulse 1.1s ease-in-out infinite; }
.loading-orbit { position: absolute; inset: 4px; border: 1px solid rgba(209,122,93,.48); border-radius: 50%; animation: orbit-spin 1.7s linear infinite; }
.loading-orbit::after { content:''; position:absolute; width:9px; height:9px; top:5px; left:14px; background:var(--clay); border-radius:50%; box-shadow:0 0 16px rgba(209,122,93,.65); }
.loading-orbit-two { inset: 17px; animation-direction: reverse; animation-duration: 1.25s; opacity: .65; }
.loading-word { margin-top: 16px; font: 500 42px/1 'Source Serif 4',serif; letter-spacing: -1px; animation: rise-in .55s ease .1s both; }
.loading-screen p { margin-top: 11px; color:var(--clay); font-size:11px; font-weight:600; letter-spacing:2.4px; text-transform:uppercase; animation: rise-in .55s ease .22s both; }
@keyframes orbit-spin { to { transform: rotate(360deg); } }
@keyframes mark-pulse { 50% { transform: scale(.9); opacity:.72; } }
@keyframes rise-in { from { opacity:0; transform:translateY(12px); } }
@keyframes loading-exit { to { opacity:0; visibility:hidden; } }

/* Vendor portal */
.vendor-app{min-height:100vh;display:grid;grid-template-columns:288px minmax(0,1fr);background:#fbfaf5}.vendor-sidebar{position:sticky;top:0;height:100vh;padding:36px 24px;background:#fff;display:flex;flex-direction:column;gap:18px;border-right:1px solid #f0e9e4}.vendor-logo{color:var(--brown);font:400 30px/1.2 'Source Serif 4',serif}.vendor-kicker{color:var(--muted);font-size:11px;font-weight:600;letter-spacing:.08em}.vendor-nav{display:grid;gap:10px;margin-top:4px}.vendor-nav a,.vendor-logout{min-height:46px;display:flex;align-items:center;gap:11px;padding:0 14px;border-radius:8px;color:var(--ink);background:transparent;font-size:14px;text-align:left}.vendor-nav a.active{color:var(--brown);background:var(--sand);font-weight:600}.vendor-nav a.active svg{color:var(--clay)}.vendor-logout{margin-top:auto;color:var(--clay)}.vendor-main{width:100%;min-width:0;padding:44px 48px 72px;display:flex;flex-direction:column;gap:28px}.vendor-header h1{color:var(--brown);font:400 clamp(32px,4vw,38px)/1.2 'Source Serif 4',serif}.vendor-header p{margin-top:6px;color:var(--muted)}
.vendor-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}.vendor-metric,.vendor-card,.vendor-package-row,.vendor-booking-row{background:#fff;border:1px solid #ede5de;border-radius:16px}.vendor-metric{min-height:132px;padding:20px;display:flex;flex-direction:column;gap:10px}.vendor-metric span{color:var(--muted);font-size:11px;font-weight:600;text-transform:uppercase}.vendor-metric strong{color:var(--brown);font:500 30px/1.1 'Source Serif 4',serif}.vendor-metric small{color:#3c835b}.vendor-grid{display:grid;gap:20px}.vendor-grid.two{grid-template-columns:minmax(0,1.7fr) minmax(280px,1fr)}.vendor-card{padding:22px}.vendor-card h2,.vendor-package-row h2,.vendor-booking-row h2{color:var(--brown);font:500 22px/1.25 'Source Serif 4',serif;margin-bottom:14px}.quick{display:flex;flex-direction:column;align-items:flex-start;gap:12px}
